					assertThat(rawCount(txn, adjacency.metadataDbi(), reference)).isEqualTo(2);
					assertThat(batch.remove(30, 20, 20, 0, false)).isTrue();
					assertThat(adjacency.count(txn, false)).isZero();
					assertThat(adjacency.isIdReferenced(txn, 20)).isFalse();
