	private static Long rawCount(long txn, int metadata, byte[] bytes) throws IOException {
		try (MemoryStack stack = MemoryStack.stackPush()) {
			MDBVal value = MDBVal.malloc(stack);
			int result = mdb_get(txn, metadata, MDBVal.malloc(stack).mv_data(stack.bytes(bytes)), value);
			if (result == MDB_NOTFOUND) {
				return null;
			}
			E(result);
			assertThat(value.mv_size()).isEqualTo(Long.BYTES);
			return value.mv_data().order(ByteOrder.BIG_ENDIAN).getLong(0);
		}
	}

	private static final class MetadataCalls implements AutoCloseable {
		final Map<Long, byte[]> positions = new HashMap<>();
		final MockedStatic<LMDB> nativeCalls;
		int opened;
		int cursorSeeks;
		int currentWrites;
		int inserts;
		int deletes;
		int directReads;
		int directPuts;
		int directDeletes;

		MetadataCalls(long txn, int metadata) {
			nativeCalls = mockStatic(LMDB.class, invocation -> {
				String method = invocation.getMethod().getName();
				if (method.equals("mdb_cursor_open")) {
					Object result = invocation.callRealMethod();
					if ((int) result == MDB_SUCCESS && (long) invocation.getArgument(0) == txn
							&& (int) invocation.getArgument(1) == metadata) {
						PointerBuffer handle = invocation.getArgument(2);
						positions.put(handle.get(0), null);
						opened++;
					}
					return result;
				}
				if (method.equals("mdb_cursor_close")) {
					positions.remove((long) invocation.getArgument(0));
				} else if ((method.equals("mdb_get") || method.equals("mdb_put") || method.equals("mdb_del"))
						&& (long) invocation.getArgument(0) == txn && (int) invocation.getArgument(1) == metadata
						&& Arrays.equals(copy(invocation.getArgument(2)), EXPLICIT_TOTAL)) {
					if (method.equals("mdb_get")) {
						directReads++;
					} else if (method.equals("mdb_put")) {
						directPuts++;
					} else {
						directDeletes++;
					}
				} else if (method.equals("mdb_cursor_get") && positions.containsKey((long) invocation.getArgument(0))) {
					long cursor = invocation.getArgument(0);
					MDBVal key = invocation.getArgument(1);
					if (Arrays.equals(copy(key), EXPLICIT_TOTAL)) {
						assertThat((int) invocation.getArgument(3)).as("metadata RMW uses an exact key seek")
								.isEqualTo(MDB_SET);
						cursorSeeks++;
					}
					Object result = invocation.callRealMethod();
					positions.put(cursor, (int) result == MDB_SUCCESS ? copy(key) : null);
					return result;
				} else if (method.equals("mdb_cursor_put") && positions.containsKey((long) invocation.getArgument(0))) {
					long cursor = invocation.getArgument(0);
					byte[] key = copy(invocation.getArgument(1));
					if (Arrays.equals(key, EXPLICIT_TOTAL)) {
						int flags = invocation.getArgument(3);
						if (flags == MDB_CURRENT) {
							currentWrites++;
						} else {
							assertThat(flags).as("new counters cannot use MDB_CURRENT").isZero();
							inserts++;
						}
					}
					Object result = invocation.callRealMethod();
					positions.put(cursor, (int) result == MDB_SUCCESS ? key : null);
					return result;
				} else if (method.equals("mdb_cursor_del") && positions.containsKey((long) invocation.getArgument(0))) {
					long cursor = invocation.getArgument(0);
					if (Arrays.equals(positions.get(cursor), EXPLICIT_TOTAL)) {
						deletes++;
					}
					positions.put(cursor, null);
				}
				return invocation.callRealMethod();
			});
		}

		private static byte[] copy(MDBVal value) {
			byte[] bytes = new byte[(int) value.mv_size()];
			value.mv_data().duplicate().get(bytes);
			return bytes;
		}

		@Override
		public void close() {
			nativeCalls.close();
		}
	}

